pub fn moved(s: Shape, d: Vec2) -> Shape {
  let add = (p: Vec2) => Vec2 { x: p.x + d.x, y: p.y + d.y };
  match s {
    Circle { center, ... } => { ...s, center: add(center) },   // s は Shape.Circle に絞り込まれている
    Rect { min, max } => { ...s, min: add(min), max: add(max) },
    Label { at, ... } => { ...s, at: add(at) },
  }
}
// JS: if (s.TAG === "Circle") return { ...s, TAG: "Circle", center: add(s.center) };
